// Step 1: Input Validation & Check Required Fields
const headers = $input.first().json.headers || {};
const body = $input.first().json.body || $input.first().json;

const correlationId = headers['x-correlation-id'] || body.correlation_id || `corr-n8n-${Date.now()}`;
const leadId = body.lead_id;
const company = body.company_name;
const email = body.email;
const rawNotes = body.raw_notes || '';

// Check mandatory fields: lead_id, company_name, email
if (!leadId || !company || !email) {
  return [{
    json: {
      is_valid: false,
      status: 'failure',
      lead_id: leadId || 'unknown',
      correlation_id: correlationId,
      error_code: 'MISSING_REQUIRED_FIELDS',
      error_summary: 'Missing required intake fields: lead_id, company_name, and email are mandatory.'
    }
  }];
}

// Validate email syntax
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(String(email).trim())) {
  return [{
    json: {
      is_valid: false,
      status: 'failure',
      lead_id: leadId,
      correlation_id: correlationId,
      error_code: 'INVALID_EMAIL_FORMAT',
      error_summary: `Malformed email address: "${email}"`
    }
  }];
}

// Valid lead intake
return [{
  json: {
    is_valid: true,
    lead_id: leadId,
    correlation_id: correlationId,
    company_name: String(company).trim(),
    contact_name: String(body.contact_name || '').trim(),
    email: String(email).toLowerCase().trim(),
    website: body.website ? String(body.website).trim() : null,
    source: body.source || 'inbound',
    raw_notes: String(rawNotes).trim(),
    timestamp: new Date().toISOString()
  }
}];

// Step 2: Normalize Lead Data & Prompt Injection Defense
const item = $input.first().json;

const domain = item.email.includes('@') ? item.email.split('@')[1] : '';
const cleanCompany = item.company_name.replace(/[^a-zA-Z0-9 ]/g, '').trim();

// Defend against prompt injection by removing dangerous delimiters and wrapping in XML fences
const sanitizedNotes = (item.raw_notes || '')
  .replace(/<\/?untrusted_lead_data>/gi, '')
  .replace(/```/g, '"""')
  .trim();

const untrustedDataFence = `<untrusted_lead_data>\nCompany: ${cleanCompany}\nContact: ${item.contact_name || 'Not provided'}\nEmail: ${item.email}\nDomain: ${domain}\nWebsite: ${item.website || 'None'}\nInbound Notes: ${sanitizedNotes || 'None'}\n</untrusted_lead_data>`;

return [{
  json: {
    ...item,
    normalized_domain: domain,
    normalized_company: cleanCompany,
    untrusted_fence: untrustedDataFence
  }
}];

// Step 3: Validate Qualification Output & Robust Parser
const inputData = $input.first().json;
const leadContext = $('Normalize Lead Data').first().json;

// Check for upstream model failure
if (inputData.error) {
  return [{
    json: {
      status: 'failure',
      lead_id: leadContext.lead_id,
      correlation_id: leadContext.correlation_id,
      error_code: 'AI_MODEL_EXECUTION_FAILED',
      error_summary: inputData.error?.message || 'Google Gemini model encountered an error.'
    }
  }];
}

// 1. Resolve raw text from LangChain/Gemini output variants
let rawText = '';
if (Array.isArray(inputData.generations) && inputData.generations[0]) {
  const g0 = inputData.generations[0];
  const g00 = Array.isArray(g0) ? g0[0] : g0;
  if (g00 && typeof g00.text === 'string') rawText = g00.text;
  else if (g00 && g00.message && typeof g00.message.content === 'string') rawText = g00.message.content;
}
if (typeof inputData === 'string') {
  rawText = inputData;
} else if (typeof inputData.text === 'string') {
  rawText = inputData.text;
} else if (typeof inputData.response === 'string') {
  rawText = inputData.response;
} else if (inputData.response && typeof inputData.response.text === 'string') {
  rawText = inputData.response.text;
} else if (typeof inputData.output === 'string') {
  rawText = inputData.output;
} else if (inputData.output && typeof inputData.output.text === 'string') {
  rawText = inputData.output.text;
} else if (typeof inputData.content === 'string') {
  rawText = inputData.content;
} else if (inputData.message && typeof inputData.message.content === 'string') {
  rawText = inputData.message.content;
} else if (inputData.qualification && (inputData.score !== undefined || inputData.score !== null)) {
  rawText = JSON.stringify(inputData);
} else {
  try {
    rawText = JSON.stringify(inputData);
  } catch (e) {
    rawText = '';
  }
}

if (!rawText || rawText.trim() === '' || rawText.trim() === '{}') {
  return [{
    json: {
      status: 'failure',
      lead_id: leadContext.lead_id,
      correlation_id: leadContext.correlation_id,
      error_code: 'AI_MODEL_EXECUTION_FAILED',
      error_summary: 'Google Gemini returned empty output or unconfigured credential.'
    }
  }];
}

// 2. Parser with multi-stage recovery
let parsed = null;

function tryParseJson(str) {
  if (!str || typeof str !== 'string') return null;
  let text = str.trim();

  // Strip markdown code fences if present
  const fenceMatch = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  if (fenceMatch) {
    text = fenceMatch[1].trim();
  } else {
    const firstBrace = text.indexOf('{');
    const lastBrace = text.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
      text = text.substring(firstBrace, lastBrace + 1).trim();
    }
  }

  // Attempt 1: Direct JSON.parse
  try {
    return JSON.parse(text);
  } catch (e) {}

  // Attempt 2: Sanitize common Gemini quirks (trailing commas, smart quotes, literal newlines in strings)
  try {
    let sanitized = text
      .replace(/[\u201C\u201D]/g, '"')
      .replace(/[\u2018\u2019]/g, "'")
      .replace(/,\s*([}\]])/g, '$1');

    // Replace unescaped control characters inside string literals
    sanitized = sanitized.replace(/"([^"\\]*(?:\\.[^"\\]*)*)"/gs, (match) => {
      return match.replace(/(?<!\\)\n/g, '\\n').replace(/(?<!\\)\r/g, '\\r').replace(/(?<!\\)\t/g, '\\t');
    });

    return JSON.parse(sanitized);
  } catch (e) {}

  return null;
}

parsed = tryParseJson(rawText);

// Stage 2B: Fallback Conversational Extraction if strict JSON parsing fails
if (!parsed || typeof parsed !== 'object') {
  const textLower = rawText.toLowerCase();

  // Extract score
  let scoreMatch = rawText.match(/(?:score|rating|points)[\s:=*#-]+(\d{1,3})/i);
  let extractedScore = scoreMatch ? parseInt(scoreMatch[1], 10) : null;

  // Extract qualification category
  let qualMatch = rawText.match(/(?:qualification|category|fit)[\s:=*#-]+(high|medium|low|insufficient_data)/i);
  let extractedQual = qualMatch ? qualMatch[1].toLowerCase() : null;

  if (!extractedQual) {
    if (extractedScore !== null) {
      if (extractedScore >= 80) extractedQual = 'high';
      else if (extractedScore >= 50) extractedQual = 'medium';
      else if (extractedScore >= 20) extractedQual = 'low';
      else extractedQual = 'insufficient_data';
    } else if (textLower.includes('high fit') || textLower.includes('high priority')) {
      extractedQual = 'high';
      extractedScore = 85;
    } else if (textLower.includes('medium fit') || textLower.includes('moderate fit')) {
      extractedQual = 'medium';
      extractedScore = 65;
    } else if (textLower.includes('low fit') || textLower.includes('unqualified')) {
      extractedQual = 'low';
      extractedScore = 30;
    } else {
      extractedQual = 'insufficient_data';
      extractedScore = 15;
    }
  }

  if (extractedScore === null) {
    extractedScore = extractedQual === 'high' ? 85 : extractedQual === 'medium' ? 65 : extractedQual === 'low' ? 30 : 10;
  }

  // Extract reason
  let reasonMatch = rawText.match(/(?:reason|rationale|summary|analysis)[\s:=*#-]+([^\n\r]+)/i);
  let extractedReason = reasonMatch ? reasonMatch[1].trim() : '';
  if (!extractedReason || extractedReason.length < 5) {
    const lines = rawText.split('\n').map(l => l.trim()).filter(l => l.length > 10 && !l.startsWith('#') && !l.startsWith('```'));
    extractedReason = lines[0] || 'Qualification completed based on inbound criteria.';
  }

  // Extract recommended next action
  let actionMatch = rawText.match(/(?:action|next[ _]action|recommended)[\s:=*#-]+(research|draft|review|skip)/i);
  let extractedAction = actionMatch ? actionMatch[1].toLowerCase() : (extractedScore >= 80 ? 'draft' : 'review');

  // Extract draft
  let draftMatch = rawText.match(/(?:outreach_draft|draft|email[ _]draft|email[ _]pitch)[\s:=*#-]+([\s\S]+?)(?:\n\n[A-Z][a-z]+:|$)/i);
  let extractedDraft = draftMatch ? draftMatch[1].trim() : null;
  if (!extractedDraft && rawText.includes('Hi ') && extractedScore >= 80) {
    const hiIndex = rawText.indexOf('Hi ');
    extractedDraft = rawText.substring(hiIndex).trim();
  }

  // Extract evidence bullet points
  const evidenceLines = [];
  const lines = rawText.split('\n');
  let inEvidence = false;
  for (const line of lines) {
    if (line.match(/evidence/i)) { inEvidence = true; continue; }
    if (inEvidence && line.match(/(?:missing|action|draft|next)/i)) { inEvidence = false; }
    if (inEvidence && line.match(/^[\s*•-]+(.+)/)) {
      evidenceLines.push(line.replace(/^[\s*•-]+/, '').trim());
    }
  }

  parsed = {
    qualification: extractedQual,
    score: extractedScore,
    reason: extractedReason,
    evidence: evidenceLines.length > 0 ? evidenceLines : ['Inbound company data matched criteria'],
    missing_information: [],
    recommended_next_action: extractedAction,
    outreach_draft: extractedDraft
  };
}

// 3. Enforce schema bounds and enums
const validCategories = ['high', 'medium', 'low', 'insufficient_data'];
const validActions = ['research', 'draft', 'review', 'skip'];

const finalCategory = validCategories.includes(parsed.qualification) ? parsed.qualification : 'insufficient_data';
const finalScore = Math.max(0, Math.min(100, Math.round(Number(parsed.score) || 0)));
const finalReason = String(parsed.reason || 'Evaluation completed.').trim();
const finalEvidence = Array.isArray(parsed.evidence) ? parsed.evidence.map(String) : [];
const finalMissing = Array.isArray(parsed.missing_information) ? parsed.missing_information.map(String) : [];
const finalAction = validActions.includes(parsed.recommended_next_action) ? parsed.recommended_next_action : 'review';
const finalDraft = (typeof parsed.outreach_draft === 'string' && parsed.outreach_draft.trim().length > 0) ? parsed.outreach_draft.trim() : null;

// Safety guard: obvious synthetic/test leads must never be promoted or drafted for outreach.
const looksSynthetic = /example\.com/i.test(String(leadContext.email || '')) || /demo test company|test user|example company/i.test(`${leadContext.company_name || ''} ${leadContext.contact_name || ''}`);
const safeCategory = looksSynthetic ? 'insufficient_data' : finalCategory;
const safeScore = looksSynthetic ? Math.min(finalScore, 10) : finalScore;
const safeAction = looksSynthetic ? 'skip' : finalAction;
const safeDraft = looksSynthetic ? null : finalDraft;

return [{
  json: {
    status: 'success',
    lead_id: leadContext.lead_id,
    correlation_id: leadContext.correlation_id,
    qualification: {
      qualification: safeCategory,
      score: safeScore,
      reason: finalReason,
      evidence: finalEvidence,
      missing_information: finalMissing,
      recommended_next_action: safeAction,
      outreach_draft: safeDraft
    }
  }
}];
